import type { FrameworkApiReference } from '../types'
import { bullMqLearningMeta } from './learning-meta'

type BullMqApiInput = Omit<FrameworkApiReference, 'slug' | 'technologySlug' | 'maturity' | 'exampleLanguage' | 'officialUrl'> & {
  officialUrl: string
  maturity?: FrameworkApiReference['maturity']
}

const bullMqApi = ({ maturity = 'stable', officialUrl, ...input }: BullMqApiInput): FrameworkApiReference => {
  const learningMeta = bullMqLearningMeta[input.name as keyof typeof bullMqLearningMeta]
  if (!learningMeta) throw new Error(`Missing structured BullMQ learning metadata for ${input.name}`)
  const [pageUrl, anchor] = officialUrl.split('#')
  const returns = input.returns.length >= 12
    ? input.returns
    : input.returns === '无返回值。'
      ? '不返回业务数据；调用只更新当前 Worker 的本地控制状态，后续效果需从任务状态和事件确认。'
      : `${input.returns}调用方应把它作为当前 Redis/队列状态的读取或变更结果，而不是长期业务事实。`
  return {
    ...input,
    ...learningMeta,
    returns,
    slug: `bullmq-${input.name.replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase()}`,
    technologySlug: 'bullmq',
    maturity,
    exampleLanguage: 'ts',
    officialUrl: anchor ? `${pageUrl}#${anchor.toLowerCase()}` : pageUrl,
  }
}

const QUEUE = 'https://api.docs.bullmq.io/classes/v5.Queue.html'
const WORKER = 'https://api.docs.bullmq.io/classes/v5.Worker.html'
const JOB = 'https://api.docs.bullmq.io/classes/v5.Job.html'
const EVENTS = 'https://api.docs.bullmq.io/classes/v5.QueueEvents.html'
const FLOW = 'https://api.docs.bullmq.io/classes/v5.FlowProducer.html'

const queueApis = [
  bullMqApi({ name: 'Queue', group: 'Queue 生产与管理', kind: 'class', signature: 'new Queue<Data, Result, Name>(name: string, opts?: QueueOptions)', beginner: 'Queue 是任务的“生产端和管理端”：把 Job 写入 Redis、查询各状态任务，并执行暂停、清理、限流等队列级操作。创建 Queue 不会处理任务，真正消费由 Worker 完成。', whenToUse: 'API 服务、定时器或业务代码需要投递任务，以及运维代码需要查询或控制队列时。', example: `import { Queue } from 'bullmq'\n\nconst emailQueue = new Queue('emails', {\n  connection: { host: '127.0.0.1', port: 6379 },\n  defaultJobOptions: { attempts: 3, removeOnComplete: 1000 },\n})`, returns: '一个轻量 Queue 实例；连接通常延迟建立，可复用它持续添加和管理任务。', interview: 'BullMQ 把任务状态保存在 Redis，Queue 只负责生产与管理。生产者和 Worker 可在不同进程/机器，通过相同 queue name、prefix 和 Redis 连接协作。', pitfall: '不要每个请求都 new Queue；复用实例并在进程退出时 close。不同环境必须使用不同 prefix/Redis，任务 data 也不应塞入超大文件。', officialUrl: QUEUE }),
  bullMqApi({ name: 'Queue.add', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.add(name: Name, data: Data, opts?: JobsOptions): Promise<Job>', beginner: '向队列写入一个 Job。name 用来区分任务类型，data 是处理所需数据，opts 可设置 jobId、delay、attempts、backoff、priority、deduplication 和自动删除策略。', whenToUse: '一次投递单个异步任务，并希望拿到创建后的 Job 对象时。', example: `const job = await emailQueue.add('welcome',\n  { userId: 'u-1' },\n  { jobId: 'welcome:u-1', attempts: 5, backoff: { type: 'exponential', delay: 1000 } },\n)`, returns: 'Promise<Job>，包含任务 id、数据、选项和后续查询/控制方法。', interview: 'add 将任务原子写入 Redis；自定义 jobId 可帮助幂等，但“相同 id 已存在”与业务幂等仍需区分，外部副作用必须自行去重。', pitfall: 'jobId 不能包含冒号；不要把密码或大二进制放在 data。生产前设计 attempts、backoff 与 removeOnComplete/Fail，否则 Redis 会持续增长。', officialUrl: `${QUEUE}#add` }),
  bullMqApi({ name: 'Queue.addBulk', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.addBulk(jobs: Array<{ name; data; opts? }>): Promise<Job[]>', beginner: '一次把多条任务批量写入同一队列，比逐条 await add 减少网络往返，并保证这一批添加操作以更紧凑的 Redis 事务完成。', whenToUse: '导入数据、批量通知或一次业务事件需要产生很多同队列任务时。', example: `const jobs = await emailQueue.addBulk(users.map(user => ({\n  name: 'digest',\n  data: { userId: user.id },\n  opts: { jobId: \`digest:\${date}:\${user.id}\` },\n})))`, returns: '按输入顺序返回 Job[]。', interview: '批量写提升吞吐并降低 RTT，但不是无限批次；要分块、处理整体失败，并为每项设置稳定幂等 id。', pitfall: '过大数组会阻塞 Redis 和占用内存；addBulk 只适合同一 Queue，跨队列依赖应使用 FlowProducer。', officialUrl: `${QUEUE}#addBulk` }),
  bullMqApi({ name: 'Queue.getJob', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getJob(jobId: string): Promise<Job | undefined>', beginner: '按 id 从 Redis 还原一条 Job。任务若已按自动删除策略清理，就会得到 undefined。', whenToUse: '状态查询、取消页面、后台补偿或按业务 jobId 检查任务是否已存在时。', example: `const job = await emailQueue.getJob(jobId)\nif (!job) return { status: 'expired-or-missing' }`, returns: '找到时返回 Job，否则 undefined。', interview: 'Job 记录不是永久审计日志；removeOnComplete/Fail 会影响可查询时间，业务长期状态应另存数据库。', pitfall: '不要把“查不到”直接解释为从未执行；它也可能已完成后被删除。对外查询还要验证 jobId 的业务归属。', officialUrl: `${QUEUE}#getJob` }),
  bullMqApi({ name: 'Queue.getJobs', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getJobs(types?, start?, end?, asc?): Promise<Job[]>', beginner: '按一个或多个状态分页读取任务，例如 waiting、active、completed、failed、delayed。start/end 是 Redis 范围索引，不是页码。', whenToUse: '构建运维列表、失败任务页面或小范围诊断时。', example: `const failed = await emailQueue.getJobs(['failed'], 0, 49, false)`, returns: '指定状态与范围内的 Job[]。', interview: '队列状态分布在不同 Redis 结构中，跨状态列表不是数据库快照；高并发下结果会随任务迁移变化。', pitfall: '不要 end=-1 拉全量大队列；分页并只取必要状态。面向用户的业务列表应来自业务数据库而非扫描 Queue。', officialUrl: `${QUEUE}#getJobs` }),
  bullMqApi({ name: 'Queue.getJobState', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getJobState(jobId: string): Promise<JobType | "unknown">', beginner: '只查询某个 jobId 当前处于 waiting、active、completed、failed、delayed、prioritized 等哪个状态，不必先加载完整 Job。', whenToUse: '轻量状态轮询、健康检查或状态机同步时。', example: `const state = await emailQueue.getJobState(jobId)\nif (state === 'failed') await alert(jobId)`, returns: '任务状态字符串；任务不存在或已清理时为 unknown。', interview: '状态是瞬时读数，读取后可能马上变化；执行控制不能只依赖“先查再改”，应使用 BullMQ 提供的原子状态转换。', pitfall: '不要把 unknown 等同 waiting；轮询设置间隔和超时，避免对 Redis 形成高频压力。', officialUrl: `${QUEUE}#getJobState` }),
  bullMqApi({ name: 'Queue.getJobCounts', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getJobCounts(...types: JobType[]): Promise<Record<JobType, number>>', beginner: '一次统计多个任务状态的数量，例如还有多少等待、正在执行、失败和延迟任务。', whenToUse: '队列看板、积压告警和简单容量判断时。', example: `const counts = await emailQueue.getJobCounts('waiting', 'active', 'failed', 'delayed')`, returns: '状态名到数量的对象。', interview: 'waiting 增长速度与处理吞吐的差值反映积压，但单个瞬时计数不足以判断趋势，应与 metrics 和时间窗口结合。', pitfall: '不要把 completed 总量当实时吞吐；完成任务可能被自动删除。告警应避免每个请求都重复统计。', officialUrl: `${QUEUE}#getJobCounts` }),
  bullMqApi({ name: 'Queue.getJobCountByTypes', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getJobCountByTypes(...types: JobType[]): Promise<number>', beginner: '把多个指定状态的任务数相加，只返回一个总数；例如计算所有“尚未结束”的任务。', whenToUse: '只关心合计而不需要每个状态拆分时。', example: `const unfinished = await queue.getJobCountByTypes('waiting', 'active', 'delayed', 'prioritized')`, returns: '指定状态任务数量之和。', interview: '聚合计数适合背压阈值，但状态组合要定义清楚；waiting-children、delayed 是否算积压取决于业务。', pitfall: '不要用这个读数实现强一致配额，“读计数再 add”存在竞态；强限制应使用全局并发、限流或业务原子键。', officialUrl: `${QUEUE}#getJobCountByTypes` }),
  bullMqApi({ name: 'Queue.getWaiting', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getWaiting(start?: number, end?: number): Promise<Job[]>', beginner: '分页读取等待 Worker 领取的普通任务。它是 getJobs(["waiting"]) 的便捷方法。', whenToUse: '诊断等待队列头部、展示少量积压样本时。', example: `const nextJobs = await queue.getWaiting(0, 19)`, returns: '等待状态 Job[]。', interview: 'waiting 是可消费队列，但优先任务位于 prioritized 结构；只看 waiting 不能完整代表待处理负载。', pitfall: '不要修改返回 Job 后假设 Redis 自动更新；数据变更要调用 updateData。大队列始终分页。', officialUrl: `${QUEUE}#getWaiting` }),
  bullMqApi({ name: 'Queue.getActive', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getActive(start?: number, end?: number): Promise<Job[]>', beginner: '分页读取已经被 Worker 领取、当前持锁处理的任务。', whenToUse: '排查长运行任务、Worker 卡住或观察当前并发时。', example: `const active = await queue.getActive(0, 49)`, returns: 'active 状态 Job[]。', interview: 'active 依赖 Worker lock；进程崩溃后任务不会永远 active，stalled 检查会重试或失败它。', pitfall: '不要仅凭 active 时间长就直接 remove；先检查 lock、处理时长和 stalled 配置，强制操作可能造成重复副作用。', officialUrl: `${QUEUE}#getActive` }),
  bullMqApi({ name: 'Queue.getCompleted', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getCompleted(start?: number, end?: number): Promise<Job[]>', beginner: '分页读取已成功完成且仍保留在 Redis 的任务。', whenToUse: '短期运维检查、查看 returnvalue 或排查最近成功任务时。', example: `const recent = await queue.getCompleted(0, 19)`, returns: '保留的 completed Job[]。', interview: 'completed 集合受 removeOnComplete 保留策略影响，因此不是可靠的长期业务报表。', pitfall: '不要无限保留完成任务；returnvalue 过大也会占 Redis。长期结果写入业务数据库或对象存储。', officialUrl: `${QUEUE}#getCompleted` }),
  bullMqApi({ name: 'Queue.getFailed', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getFailed(start?: number, end?: number): Promise<Job[]>', beginner: '分页读取超过重试或被明确标记为失败、且仍保留的任务。', whenToUse: '失败运维页面、人工补偿和错误原因抽样时。', example: `const failures = await queue.getFailed(0, 49)\nfor (const job of failures) console.log(job.id, job.failedReason)`, returns: 'failed Job[]。', interview: '失败队列相当于简化 DLQ，但是否永久保留由 removeOnFail 决定；重试前要区分瞬时错误和永久业务错误。', pitfall: '不要无脑 retryJobs 全部失败项；先修复根因并确保 processor 幂等，避免毒任务循环冲击依赖。', officialUrl: `${QUEUE}#getFailed` }),
  bullMqApi({ name: 'Queue.getDelayed', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getDelayed(start?: number, end?: number): Promise<Job[]>', beginner: '读取尚未到执行时间的延迟任务，包括 delay、backoff 或调度器产生的下一次任务。', whenToUse: '检查定时任务、退避重试或延迟积压时。', example: `const delayed = await queue.getDelayed(0, 99)`, returns: 'delayed Job[]。', interview: 'delay 表示最早可执行时间，不保证精确准点；到期后还受 Worker 可用性、并发和限流影响。', pitfall: '不要把 BullMQ 当硬实时调度器；Redis/Worker 停机和积压都会造成晚执行。', officialUrl: `${QUEUE}#getDelayed` }),
  bullMqApi({ name: 'Queue.getPrioritized', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getPrioritized(start?: number, end?: number): Promise<Job[]>', beginner: '读取带 priority、等待按优先级调度的任务；数值越小通常优先级越高，0 表示无优先级。', whenToUse: '排查高优先级任务是否被正确插队、查看优先队列积压时。', example: `const urgent = await queue.getPrioritized(0, 19)`, returns: 'prioritized Job[]。', interview: '优先级会引入额外 Redis 操作并可能造成低优任务饥饿；通常要配合业务分队列或公平策略。', pitfall: '不要把 priority 当安全等级，也不要使用过多离散值；读取 waiting 时不会自动包含 prioritized。', officialUrl: `${QUEUE}#getPrioritized` }),
  bullMqApi({ name: 'Queue.getWaitingChildren', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getWaitingChildren(start?: number, end?: number): Promise<Job[]>', beginner: '读取 Flow 中正在等待子任务完成的父 Job；子任务全部满足依赖条件后，父任务才进入可处理状态。', whenToUse: '排查 Flow 卡住、查看父子依赖执行情况时。', example: `const blockedParents = await queue.getWaitingChildren(0, 49)`, returns: 'waiting-children 状态的父 Job[]。', interview: 'Flow 是依赖图状态机，父 Job 的可运行条件由子任务结果和 failParent/ignoreDependency 等策略决定。', pitfall: '不要把 waiting-children 当普通积压；先检查依赖、失败子项和跨队列 Worker 是否在线。', officialUrl: `${QUEUE}#getWaitingChildren` }),
  bullMqApi({ name: 'Queue.getJobLogs', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getJobLogs(jobId: string, start?, end?, asc?): Promise<{ logs; count }>', beginner: '读取 processor 通过 job.log 写入的任务级日志，比全局服务日志更容易按 jobId 查看执行过程。', whenToUse: '任务详情页、失败排查和给用户展示有限处理进度时。', example: `const { logs, count } = await queue.getJobLogs(jobId, 0, 99, true)`, returns: '日志字符串数组和总条数。', interview: 'Job log 适合任务上下文，应用 log 适合全局检索；生产常用 jobId/traceId 把两者关联。', pitfall: '设置 keepLogs，避免每个任务无限增长；不要记录密钥、完整个人数据或超长 payload。', officialUrl: `${QUEUE}#getJobLogs` }),
  bullMqApi({ name: 'Queue.clean', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.clean(grace: number, limit: number, type?: JobType): Promise<string[]>', beginner: '删除某状态中“超过 grace 毫秒”的旧任务，最多删 limit 条，并返回被删 jobId。', whenToUse: '按保留期批量清理 completed、failed、delayed 等历史数据时。', example: `const removedIds = await queue.clean(7 * 24 * 3600_000, 1000, 'completed')`, returns: '被删除任务的 id 数组。', interview: 'clean 是批次保留策略；优先在 job options 用 removeOnComplete/Fail 自动保留，运维 clean 作为补充。', pitfall: 'grace 是年龄不是绝对时间；小批循环清理并监控 Redis 延迟，误选状态可能删除仍需调查的数据。', officialUrl: `${QUEUE}#clean` }),
  bullMqApi({ name: 'Queue.drain', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.drain(delayed?: boolean): Promise<void>', beginner: '清空等待队列；可选择同时清除 delayed，但不会删除 active、completed 或 failed 任务。', whenToUse: '测试重置、取消尚未开始的批次，或明确放弃当前积压时。', example: `await queue.pause()\nawait queue.drain(true)`, returns: '清空操作完成的 Promise。', interview: 'drain 是破坏性队列控制，范围比 obliterate 小；为了减少新任务同时进入，常先暂停生产/队列。', pitfall: '生产执行前做二次确认和审计；Flow 父子关系或其他队列依赖不会自动完整清理。', officialUrl: `${QUEUE}#drain` }),
  bullMqApi({ name: 'Queue.obliterate', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.obliterate(opts?: { force?: boolean; count?: number }): Promise<void>', beginner: '彻底删除这个队列的全部 BullMQ Redis 数据，类似“销毁队列”，比 drain 强得多。', whenToUse: '测试环境重建、废弃队列或有严格运维流程的全量清除时。', example: `await queue.pause()\nawait queue.obliterate({ force: true })`, returns: '队列数据删除完成的 Promise。', interview: 'obliterate 是不可逆管理操作；force 可在 active job 存在时强制执行，因此必须与 Worker 停止和业务补偿协调。', pitfall: '不要在普通请求路径暴露；先停生产者/Worker、备份所需数据并确认 prefix/queue name，避免删错环境。', officialUrl: `${QUEUE}#obliterate` }),
  bullMqApi({ name: 'Queue.pause', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.pause(): Promise<void>', beginner: '全局暂停队列，使 Worker 不再领取新的 Job；已经 active 的任务通常继续运行到结束。状态保存在 Redis，对所有 Worker 生效。', whenToUse: '维护、故障止损、部署迁移或需要暂时阻止新任务消费时。', example: `await queue.pause()`, returns: '全局暂停完成的 Promise。', interview: 'Queue.pause 是全局消费闸门，Worker.pause 只暂停某个 Worker 实例；这是面试常见区别。', pitfall: '暂停不阻止生产者 add，也不会取消 active job；维护结束必须 resume，并监控暂停期间积压。', officialUrl: `${QUEUE}#pause` }),
  bullMqApi({ name: 'Queue.resume', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.resume(): Promise<void>', beginner: '解除 Queue 的全局暂停，让所有可用 Worker 继续领取等待任务。', whenToUse: '维护或故障处理完成，确认下游容量足够后恢复消费时。', example: `await queue.resume()`, returns: '恢复完成的 Promise。', interview: '恢复瞬间可能释放大量积压，生产系统应配合全局并发、限流和渐进扩容，避免惊群。', pitfall: '不要未检查失败原因就恢复；先确认 Worker、数据库和第三方依赖健康，并观察 backlog 下降速度。', officialUrl: `${QUEUE}#resume` }),
  bullMqApi({ name: 'Queue.isPaused', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.isPaused(): Promise<boolean>', beginner: '查询队列是否处于全局暂停状态。它不代表某个具体 Worker 是否本地暂停。', whenToUse: '运维面板、恢复前检查和健康状态展示时。', example: `const globallyPaused = await queue.isPaused()`, returns: '全局暂停返回 true，否则 false。', interview: 'Queue 状态与 Worker 本地状态属于两个控制层；完整诊断还应查看 Worker 数量和积压。', pitfall: '读取后状态仍可能变化，不要用“先 isPaused 再 resume”实现需要原子性的业务流程。', officialUrl: `${QUEUE}#isPaused` }),
  bullMqApi({ name: 'Queue.promoteJobs', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.promoteJobs(opts?: { count?: number }): Promise<void>', beginner: '批量把到期前的 delayed 任务提前移入可处理队列，让它们尽快被 Worker 领取。', whenToUse: '取消等待窗口、人工加速延迟批次或测试 delayed 行为时。', example: `await queue.promoteJobs({ count: 100 })`, returns: '批量提升完成的 Promise。', interview: 'promote 改变调度时间但不绕过队列暂停、并发和限流；高峰批量提升会制造瞬时积压。', pitfall: '分批操作并确认业务允许提前执行；Job Scheduler 产生的下一次任务不要随意批量 promote。', officialUrl: `${QUEUE}#promoteJobs` }),
  bullMqApi({ name: 'Queue.retryJobs', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.retryJobs(opts?: { count?; state?; timestamp? }): Promise<void>', beginner: '批量把 failed 或 completed 中符合条件的任务移回等待队列，重新交给 Worker 处理。', whenToUse: '修复系统性故障后，对一批历史任务做受控补偿时。', example: `await queue.retryJobs({ count: 200, state: 'failed' })`, returns: '批量重试操作完成的 Promise。', interview: '重试是至少一次交付的一部分，processor 必须幂等；批量重试前应按错误类型、时间和版本筛选。', pitfall: '不要对永久业务错误或毒任务全量重试；先限制 count、降并发，并确认外部副作用不会重复。', officialUrl: `${QUEUE}#retryJobs` }),
  bullMqApi({ name: 'Queue.close', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.close(): Promise<void>', beginner: '优雅关闭 Queue 使用的 Redis 连接，并等待正在进行的客户端操作收尾。', whenToUse: '进程收到 SIGTERM、测试结束或应用生命周期关闭时。', example: `process.on('SIGTERM', async () => {\n  await queue.close()\n})`, returns: '关闭完成的 Promise。', interview: '生产者也需要 graceful shutdown，避免请求已接受但 add 尚未写入就断开。close 与 disconnect 的强制语义不同。', pitfall: '不要在每次 add 后 close；共享连接的生命周期要统一管理，并给关停设置总超时。', officialUrl: `${QUEUE}#close` }),
  bullMqApi({ name: 'Queue.disconnect', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.disconnect(): Promise<void>', beginner: '强制断开 Redis 连接，不等待完整优雅收尾，通常只在连接异常或快速终止时使用。', whenToUse: '无法优雅 close、测试需要模拟掉线或进程必须快速退出时。', example: `await queue.disconnect()`, returns: '连接断开完成的 Promise。', interview: 'disconnect 可能让在途命令失败，close 更适合正常关停；两者体现 graceful 与 forceful shutdown 的权衡。', pitfall: '不要把 disconnect 当普通资源释放；调用后复用实例可能失败，先处理未完成的 add 与错误。', officialUrl: `${QUEUE}#disconnect` }),
  bullMqApi({ name: 'Queue.waitUntilReady', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.waitUntilReady(): Promise<RedisClient>', beginner: '等待底层 Redis 连接真正可用，适合启动探针或必须确认依赖就绪后再接收流量。', whenToUse: '应用启动、readiness check 或初始化流程需要显式等待 Redis 时。', example: `await queue.waitUntilReady()\nserver.listen(port)`, returns: '已连接的 Redis client。', interview: '构造 Queue 并不等于 Redis 已可用；readiness 应反映关键依赖，但健康检查不能每次新建连接。', pitfall: '设置外层启动超时并处理连接失败；不要把返回 client 用于任意 Redis 命令破坏 BullMQ key 约定。', officialUrl: `${QUEUE}#waitUntilReady` }),
  bullMqApi({ name: 'Queue.trimEvents', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.trimEvents(maxLength: number): Promise<number>', beginner: '手动裁剪 QueueEvents 使用的 Redis Stream，只保留大约 maxLength 条全局事件，控制 Redis 占用。', whenToUse: '默认自动裁剪不满足保留策略，或运维需要立即缩短事件流时。', example: `const trimmed = await queue.trimEvents(10_000)`, returns: 'Redis 裁剪命令返回的删除/处理数量。', interview: 'QueueEvents 基于 Redis Streams，比 Pub/Sub 更耐短暂断线，但事件流仍有保留上限，不是永久事件仓库。', pitfall: '裁剪过小会让离线消费者错过事件；关键业务状态应从 Job/数据库恢复，不能只依赖事件流重放。', officialUrl: `${QUEUE}#trimEvents` }),
  bullMqApi({ name: 'Queue.setGlobalConcurrency', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.setGlobalConcurrency(concurrency: number): Promise<number>', beginner: '设置整条队列跨所有 Worker 的最大同时 active 数，不管部署了多少进程，都受这个全局上限约束。', whenToUse: '保护数据库、第三方 API 或许可证席位等共享下游容量时。', example: `await queue.setGlobalConcurrency(20)`, returns: 'Redis 设置结果/当前值。', interview: 'Worker concurrency 是单实例并发，全局 concurrency 是全队列分布式上限；两者共同决定实际吞吐。', pitfall: '值过低会造成积压，过高会压垮下游；变更后用 metrics 观察延迟和失败率。', officialUrl: `${QUEUE}#setGlobalConcurrency` }),
  bullMqApi({ name: 'Queue.getGlobalConcurrency', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getGlobalConcurrency(): Promise<number | null>', beginner: '读取队列当前跨所有 Worker 生效的全局并发上限；如果从未设置或已移除，就返回空值。', whenToUse: '运维面板、配置漂移检查和扩缩容决策时。', example: `const limit = await queue.getGlobalConcurrency()`, returns: '设置的并发数或 null。', interview: '配置读数需要与 active count、Worker concurrency 和处理时长一起解释，不能单独推导吞吐。', pitfall: '不要把 null 当 0；null 表示没有额外全局限制。读取值不是权限控制。', officialUrl: `${QUEUE}#getGlobalConcurrency` }),
  bullMqApi({ name: 'Queue.removeGlobalConcurrency', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.removeGlobalConcurrency(): Promise<number>', beginner: '移除全队列并发上限，之后实际并发只受各 Worker concurrency 和资源能力约束。', whenToUse: '不再需要共享上限，或改用其他容量控制方案时。', example: `await queue.removeGlobalConcurrency()`, returns: 'Redis 删除结果。', interview: '移除分布式闸门可能瞬间提升吞吐，必须把它当生产配置变更而不是普通清理。', pitfall: '高积压时移除会产生流量尖峰；先评估所有 Worker 的合计并发和下游连接池。', officialUrl: `${QUEUE}#removeGlobalConcurrency` }),
  bullMqApi({ name: 'Queue.getWorkers', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getWorkers(): Promise<WorkerInfo[]>', beginner: '读取在 Redis 中登记的 Worker 信息，帮助查看有哪些消费者、并发和运行元数据。', whenToUse: '运维发现、队列无消费排查和容量面板时。', example: `const workers = await queue.getWorkers()`, returns: 'WorkerInfo 数组。', interview: 'Worker 注册信息有存活时效，适合运维发现但不是强一致服务注册中心；结合 heartbeat/stalled 与外部容器指标判断。', pitfall: '不要向普通客户端暴露主机等内部信息；短暂网络分区会让列表与真实进程有时间差。', officialUrl: `${QUEUE}#getWorkers` }),
  bullMqApi({ name: 'Queue.getWorkersCount', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.getWorkersCount(): Promise<number>', beginner: '只返回当前队列登记的 Worker 数量，比拉取完整 WorkerInfo 更轻量。', whenToUse: '“是否有消费者”健康检查和简单扩缩容监控时。', example: `const workerCount = await queue.getWorkersCount()\nif (workerCount === 0) alert('队列无人消费')`, returns: 'Worker 数量。', interview: 'Worker 数不等于处理能力；还受每实例 concurrency、暂停状态、任务耗时和全局限制影响。', pitfall: '不要仅用 count>0 判断健康；Worker 可能卡住、暂停或无法访问下游。', officialUrl: `${QUEUE}#getWorkersCount` }),
  bullMqApi({ name: 'Queue.isMaxed', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.isMaxed(): Promise<boolean>', beginner: '判断队列是否已达到全局并发上限，达到时新的任务暂时不会进入 active。', whenToUse: '诊断积压原因、运维显示“受全局并发限制”状态时。', example: `const saturated = await queue.isMaxed()`, returns: '达到全局 concurrency 返回 true。', interview: 'maxed 表示容量闸门饱和，不一定是故障；结合处理延迟和 backlog 判断是否扩容或调高限制。', pitfall: '状态是瞬时的，不要用它在生产者侧决定是否 add；队列本身就是吸收突发的缓冲层。', officialUrl: `${QUEUE}#isMaxed` }),
  bullMqApi({ name: 'Queue.remove', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.remove(jobId: string, opts?: { removeChildren?: boolean }): Promise<number>', beginner: '按 jobId 从队列删除任务，可选择处理子任务；active 且持锁的任务通常不能安全删除。', whenToUse: '后台取消尚未执行任务，或按业务 id 清理单个任务时。', example: `const removed = await queue.remove(jobId, { removeChildren: true })`, returns: '表示删除结果/数量的数字。', interview: '删除 Redis 中的 Job 记录不等于撤销已经发生的外部副作用；任务取消需要业务层状态和 processor 协作。', pitfall: '先检查权限与状态；Flow 删除可能影响父子依赖，active job 应使用 Worker 取消信号或业务取消标志。', officialUrl: `${QUEUE}#remove` }),
]

const workerApis = [
  bullMqApi({ name: 'Worker', group: 'Worker 消费执行', kind: 'class', signature: 'new Worker<Data, Result, Name>(name, processor?, opts)', beginner: 'Worker 是任务“消费者”：从 Redis 领取 Job、加锁、调用 processor，并根据返回/异常把任务移动到 completed 或 failed。创建后默认自动开始处理。', whenToUse: '独立后台进程或服务需要消费某个队列并执行真实业务逻辑时。', example: `const worker = new Worker('emails', async (job, token, signal) => {\n  await sendEmail(job.data, { signal })\n  return { sent: true }\n}, { connection, concurrency: 10 })`, returns: '一个持续运行的 Worker 实例，并通过事件报告完成、失败、进度和 stalled。', interview: 'BullMQ 默认是 at-least-once：锁过期或 Worker 崩溃可能让 Job 再执行，所以 processor 必须幂等，并避免阻塞事件循环导致 lock 无法续期。', pitfall: 'Redis 连接的 maxRetriesPerRequest 要按 Worker 要求配置；CPU 密集任务用 sandboxed processor/线程，关停时 await worker.close()。', officialUrl: WORKER }),
  bullMqApi({ name: 'Worker.on', group: 'Worker 消费执行', kind: 'function', signature: 'worker.on(event: WorkerEvent, listener): this', beginner: '监听这个 Worker 实例产生的本地事件，如 completed、failed、progress、stalled、drained 和 error。completed/failed 只覆盖该 Worker 处理到的任务。', whenToUse: '本进程日志、局部指标、错误监控和处理后钩子时。', example: `worker.on('completed', job => logger.info({ jobId: job.id }))\nworker.on('failed', (job, err) => logger.error({ jobId: job?.id, err }))\nworker.on('error', err => logger.error(err))`, returns: 'Worker 自身，支持链式注册。', interview: 'Worker events 是进程本地 EventEmitter；想集中监听所有 Worker 的全局事件应使用 QueueEvents（Redis Streams）。', pitfall: '必须监听 error，避免未处理错误；不要在监听器执行慢任务或抛异常，业务后续动作更适合投递新 Job。', officialUrl: `${WORKER}#on` }),
  bullMqApi({ name: 'Worker.pause', group: 'Worker 消费执行', kind: 'function', signature: 'worker.pause(doNotWaitActive?: boolean): Promise<void>', beginner: '只暂停当前 Worker 领取新任务。默认会等待当前 active Job 完成；doNotWaitActive=true 会更快返回但不会魔法取消在途业务。', whenToUse: '单实例滚动发布、局部维护或缩容时。', example: `await worker.pause()\nawait deployLocalChange()\nworker.resume()`, returns: '本地暂停完成的 Promise。', interview: 'Worker.pause 是实例级控制，Queue.pause 是 Redis 中的全局控制；优雅发布通常暂停实例并等待 active 清空。', pitfall: '不要把 pause 当取消；其他 Worker 仍继续消费，doNotWaitActive 也可能留下在途处理。', officialUrl: `${WORKER}#pause` }),
  bullMqApi({ name: 'Worker.resume', group: 'Worker 消费执行', kind: 'function', signature: 'worker.resume(): void', beginner: '让本地暂停的 Worker 再次领取 Job；不会解除 Queue 的全局 pause。', whenToUse: '局部维护完成，恢复当前实例消费时。', example: `worker.resume()`, returns: '无返回值。', interview: '本地 resume 只有在队列全局未暂停时才能真正取到任务，说明控制面有多层闸门。', pitfall: '不要误写 await 期待异步确认；恢复前确认 processor 依赖已健康。', officialUrl: `${WORKER}#resume` }),
  bullMqApi({ name: 'Worker.close', group: 'Worker 消费执行', kind: 'function', signature: 'worker.close(force?: boolean): Promise<void>', beginner: '优雅停止 Worker 领取任务并等待当前任务结束后关闭连接。force=true 会更快退出，但可能让 active Job 之后被判 stalled 并重新执行。', whenToUse: 'SIGTERM、滚动发布、测试结束和正常缩容时。', example: `process.on('SIGTERM', async () => {\n  await worker.close()\n  process.exit(0)\n})`, returns: 'Worker 完整关闭后的 Promise。', interview: '优雅关停减少重复执行；Kubernetes terminationGracePeriod 必须大于典型任务收尾时间，并配合 processor 的 AbortSignal。', pitfall: '不要立即 process.exit；force 关闭前确认幂等。设置应用级最大关停时间，防止永远等待卡死任务。', officialUrl: `${WORKER}#close` }),
  bullMqApi({ name: 'Worker.disconnect', group: 'Worker 消费执行', kind: 'function', signature: 'worker.disconnect(): Promise<void>', beginner: '强制断开 Worker Redis 连接，主要用于异常恢复或测试，不保证 active Job 优雅完成。', whenToUse: '连接已不可用、模拟断线或必须立即终止时。', example: `await worker.disconnect()`, returns: '断开连接完成的 Promise。', interview: '断连会停止 lock 续期，其他 Worker 可能把任务当 stalled 重做，因此 processor 幂等是基础保证。', pitfall: '正常部署优先 close；断开后不要继续使用同一 Worker 实例处理任务。', officialUrl: `${WORKER}#disconnect` }),
  bullMqApi({ name: 'Worker.run', group: 'Worker 消费执行', kind: 'function', signature: 'worker.run(): Promise<void>', beginner: '手动启动 Worker 的消费循环。只有构造时设置 autorun:false 才通常需要调用；默认 Worker 已自动运行。', whenToUse: '希望先完成依赖初始化、注册监听器或通过外部开关决定何时开始消费时。', example: `const worker = new Worker('emails', processor, { connection, autorun: false })\nawait prepareDependencies()\nvoid worker.run()`, returns: '消费循环结束/Worker 关闭时完成的 Promise。', interview: 'run 是长生命周期循环，不应在 HTTP 请求中 await 到完成；启动顺序可避免 Worker 在依赖未就绪时抢到任务。', pitfall: '不要对已运行 Worker 重复 run；要捕获返回 Promise 的错误，并确保关停路径能 close。', officialUrl: `${WORKER}#run` }),
  bullMqApi({ name: 'Worker.isPaused', group: 'Worker 消费执行', kind: 'function', signature: 'worker.isPaused(): boolean', beginner: '同步查看当前 Worker 实例是否本地暂停，不会查询 Queue 的全局暂停状态。', whenToUse: '进程内健康状态、调试和局部管理端展示时。', example: `if (worker.isPaused()) logger.warn('worker locally paused')`, returns: '本地暂停为 true。', interview: 'Worker 状态来自本进程内存，Queue.isPaused 来自 Redis；分布式诊断需要分别看两者。', pitfall: '不要用它判断整个队列无人消费；其他 Worker 可能仍在运行。', officialUrl: `${WORKER}#isPaused` }),
  bullMqApi({ name: 'Worker.isRunning', group: 'Worker 消费执行', kind: 'function', signature: 'worker.isRunning(): boolean', beginner: '同步判断 Worker 消费循环是否已经启动且尚未停止。', whenToUse: '启动保护、测试断言和本地健康诊断时。', example: `if (!worker.isRunning()) void worker.run()`, returns: '运行中返回 true。', interview: 'running 只表示循环状态，不证明 Redis、processor 下游或任务吞吐健康。', pitfall: '不要仅用 isRunning 作为生产 readiness；还要观测 error、Worker 注册、active/failed 和依赖探针。', officialUrl: `${WORKER}#isRunning` }),
  bullMqApi({ name: 'Worker.waitUntilReady', group: 'Worker 消费执行', kind: 'function', signature: 'worker.waitUntilReady(): Promise<RedisClient>', beginner: '等待 Worker 的 Redis 连接可用，便于在启动探针通过后才宣告服务 ready。', whenToUse: '应用启动、集成测试和显式依赖就绪检查时。', example: `await worker.waitUntilReady()\nmarkReady()`, returns: '已连接的 Redis client。', interview: '进程存活不等于消费者可用；readiness 应在连接和关键 processor 依赖都准备好后通过。', pitfall: '外层加启动超时；不要随意用返回 client 修改 BullMQ 私有 key。', officialUrl: `${WORKER}#waitUntilReady` }),
  bullMqApi({ name: 'Queue.rateLimit', group: 'Queue 生产与管理', kind: 'function', signature: 'queue.rateLimit(expireTimeMs: number): Promise<void>', beginner: '立刻把整个队列置于动态限流状态，在 expireTimeMs 毫秒内暂停领取新任务。BullMQ 5.80.4 已把 Worker.rateLimit 标记为 deprecated，推荐从 Queue 调用。', whenToUse: 'processor 收到第三方 429/Retry-After，需要让所有 Worker 共同等待一段动态时间时。', example: `if (response.status === 429) {\n  const waitMs = Number(response.headers.get('retry-after')) * 1000\n  await emailQueue.rateLimit(waitMs)\n  throw Worker.RateLimitError()\n}`, returns: 'Promise<void>；Redis 中的队列级限流 TTL 写入完成。', interview: 'Queue.rateLimit 是跨 Worker 的调度控制，不是普通失败重试；processor 仍应抛 Worker.RateLimitError，使当前 Job 回到等待且不消耗 attempts。', pitfall: '队列仍需配置 limiter.max 才会启用该机制；严格换算 Retry-After 单位并设置最大等待。不要继续使用计划在 v6 删除的 Worker.rateLimit。', officialUrl: `${QUEUE}#rateLimit` }),
  bullMqApi({ name: 'Worker.cancelJob', group: 'Worker 消费执行', kind: 'function', signature: 'worker.cancelJob(jobId: string, reason?: string): boolean', beginner: '取消当前 Worker 正在处理的指定 Job，processor 收到 AbortSignal；它是协作式取消，不会强行回滚已完成的副作用。', whenToUse: '用户撤销长任务，且当前 processor 已正确监听 signal 时。', example: `const accepted = worker.cancelJob(jobId, 'user requested cancellation')`, returns: '本 Worker 找到并发出取消信号则 true，否则 false。', interview: '取消需要从控制面传播到执行函数，底层 HTTP/数据库调用也要接受 signal；仅删除 Job 无法安全停止正在运行的代码。', pitfall: 'processor 不监听 signal 就不会及时停；对外取消前校验 jobId 归属，并设计业务补偿。', officialUrl: `${WORKER}#cancelJob` }),
  bullMqApi({ name: 'Worker.cancelAllJobs', group: 'Worker 消费执行', kind: 'function', signature: 'worker.cancelAllJobs(reason?: string): void', beginner: '向当前 Worker 的全部 active processor 发送取消信号，适合紧急止损或快速关停。', whenToUse: '本实例依赖故障、进程即将终止或必须停止所有在途工作时。', example: `worker.cancelAllJobs('dependency unavailable')`, returns: '无返回值。', interview: '批量取消仍是协作式；Job 后续状态与 processor 如何响应 AbortError 有关，需要统一异常约定。', pitfall: '不会影响其他 Worker；外部副作用不自动撤销，执行前确认 processor 对取消的处理一致。', officialUrl: `${WORKER}#cancelAllJobs` }),
  bullMqApi({ name: 'Worker.getNextJob', group: 'Worker 消费执行', kind: 'function', signature: 'worker.getNextJob(token: string, options?): Promise<Job | undefined>', beginner: '手动从队列领取下一条 Job，用于你自己控制取任务循环；普通应用让 Worker 自动 run 即可。', whenToUse: '实现特殊拉取节奏、嵌入已有循环或官方“manually fetching jobs”模式时。', example: `const token = crypto.randomUUID()\nconst job = await worker.getNextJob(token)\nif (job) await worker.processJob(job, token, () => false)`, returns: '领取到的 Job，暂时无任务时为 undefined。', interview: '手动取任务意味着你要承担 token、lock、stalled 检查和状态转换，属于高级控制面。', pitfall: '不要只 getNextJob 后自己执行函数而不完成/失败状态；还要启动 stalled checker 并正确管理 lock。', officialUrl: `${WORKER}#getNextJob` }),
  bullMqApi({ name: 'Worker.extendJobLocks', group: 'Worker 消费执行', kind: 'function', signature: 'worker.extendJobLocks(jobIds: string[], tokens: string[], duration: number): Promise<string[]>', beginner: '批量延长当前 Worker 持有任务的 Redis lock，防止长任务被误判 stalled。自动 Worker 通常会自行续锁。', whenToUse: '高级手动取任务或自定义执行循环需要自行维护锁时。', example: `const failedJobIds = await worker.extendJobLocks([job.id!], [token], 30_000)\nif (failedJobIds.length) console.warn('续锁失败', failedJobIds)`, returns: '返回未能成功续锁的 Job ID 字符串数组；空数组表示本批没有失败项。', interview: 'lock 是 at-least-once 的核心：返回的是续锁失败的 jobIds，调用方必须逐项处理；失锁后任务可能被其他消费者重做。', pitfall: 'jobIds 与 tokens 必须同序，token 也必须与领取时一致；普通模式不要干预自动续锁，CPU 阻塞仍会让续锁定时器来不及运行。', officialUrl: `${WORKER}#extendJobLocks` }),
  bullMqApi({ name: 'Worker.startStalledCheckTimer', group: 'Worker 消费执行', kind: 'function', signature: 'worker.startStalledCheckTimer(): Promise<void>', beginner: '手动启动 stalled 检查定时器。正常 run 会自动启动，只有手动 fetching 模式才通常需要显式调用。', whenToUse: '自定义 getNextJob 循环仍希望 BullMQ 检测失锁任务时。', example: `await worker.startStalledCheckTimer()`, returns: '检查器启动完成的 Promise。', interview: 'BullMQ 2+ 不需要独立 QueueScheduler 来处理 stalled，Worker 自身承担检查；这是旧版与 v5 的关键区别。', pitfall: '自动模式不要重复启动；stalledInterval 太短会增加 Redis 压力，太长会延迟故障恢复。', officialUrl: `${WORKER}#startStalledCheckTimer` }),
]

const jobApis = [
  bullMqApi({ name: 'Job', group: 'Job 状态与控制', kind: 'class', signature: 'Job<Data, Result, Name>', beginner: 'Job 是一条任务记录，包含 id、name、data、opts、progress、attemptsMade、returnvalue、failedReason 和时间戳。通常由 Queue.add 创建，并作为参数传给 processor。', whenToUse: 'processor 读取任务输入、更新进度，或管理端查询和控制单个任务时。', example: `const worker = new Worker('emails', async job => {\n  console.log(job.id, job.name, job.data, job.attemptsMade)\n  return { sent: true }\n})`, returns: 'Job 实例的方法会读写 Redis 中这条任务的状态。', interview: 'Job 是持久化状态机，不只是消息 payload；状态转换由 Lua/锁保证原子性，业务副作用仍需幂等。', pitfall: '不要直接修改 job.data/progress 后期待持久化；调用 updateData/updateProgress。自动删除后旧实例也不能代表 Redis 仍有记录。', officialUrl: JOB }),
  bullMqApi({ name: 'Job.updateData', group: 'Job 状态与控制', kind: 'function', signature: 'job.updateData(data: Data): Promise<void>', beginner: '用新对象完整替换 Job 的 data，并保存到 Redis。', whenToUse: '任务尚未结束，需要持久化下一阶段输入或修正可重试参数时。', example: `await job.updateData({ ...job.data, normalized: true })`, returns: '更新完成的 Promise。', interview: '这是整体替换而非字段级事务；并发写入可能互相覆盖，复杂状态应放业务数据库。', pitfall: '不要存大对象或敏感信息；更新前考虑 Worker/管理端同时修改的竞态。', officialUrl: `${JOB}#updateData` }),
  bullMqApi({ name: 'Job.updateProgress', group: 'Job 状态与控制', kind: 'function', signature: 'job.updateProgress(progress: number | object): Promise<void>', beginner: '把进度数字或结构化对象写入 Redis，并触发 progress 事件供界面实时显示。', whenToUse: '长任务有明确阶段或百分比，需要外部观察执行进度时。', example: `await job.updateProgress({ percent: 50, stage: 'uploading' })`, returns: '进度保存完成的 Promise。', interview: '进度是可观察状态而非事务保证；更新频率要限流，断线后客户端可从 Job 当前 progress 恢复。', pitfall: '不要每个循环元素都写 Redis；节流并保持对象 schema 稳定，避免 UI 无法解析旧版本。', officialUrl: `${JOB}#updateProgress` }),
  bullMqApi({ name: 'Job.log', group: 'Job 状态与控制', kind: 'function', signature: 'job.log(logRow: string): Promise<number>', beginner: '为当前 Job 追加一行任务日志，方便在 Job 详情中查看处理过程。', whenToUse: '记录少量业务阶段、重试原因和可向用户展示的诊断信息时。', example: `const rows = await job.log('开始上传生成结果')`, returns: '当前任务日志总条数。', interview: 'Job log 与任务绑定，便于局部排查；全局结构化日志仍应包含 jobId/traceId 用于跨服务查询。', pitfall: '设置 keepLogs 并脱敏；高频日志会增加 Redis 内存和命令量。', officialUrl: `${JOB}#log` }),
  bullMqApi({ name: 'Job.clearLogs', group: 'Job 状态与控制', kind: 'function', signature: 'job.clearLogs(keepLogs?: number): Promise<void>', beginner: '清空任务日志，或只保留最后 keepLogs 行。', whenToUse: '任务日志过多、合规清理或只需保留尾部诊断时。', example: `await job.clearLogs(100)`, returns: '裁剪完成的 Promise。', interview: '日志保留属于数据生命周期设计；清理 Redis 日志不等于清理外部日志平台副本。', pitfall: '不要在故障调查前误删证据；对合规删除要覆盖所有副本。', officialUrl: `${JOB}#clearLogs` }),
  bullMqApi({ name: 'Job.getState', group: 'Job 状态与控制', kind: 'function', signature: 'job.getState(): Promise<JobType | "unknown">', beginner: '查询这条 Job 当前实际状态；比读取旧实例字段可靠，因为状态会由其他 Worker 在 Redis 中改变。', whenToUse: '状态页、控制操作前检查和调试时。', example: `const state = await job.getState()`, returns: '当前状态或 unknown。', interview: '查询与后续操作之间仍有竞态，真正状态转换必须调用 BullMQ 原子方法。', pitfall: 'unknown 可能表示已自动删除，不等于从未存在。', officialUrl: `${JOB}#getState` }),
  bullMqApi({ name: 'Job.isWaiting', group: 'Job 状态与控制', kind: 'function', signature: 'job.isWaiting(): Promise<boolean>', beginner: '判断任务是否在普通等待队列，尚未被 Worker 领取。', whenToUse: '取消或诊断前做可读状态判断时。', example: `if (await job.isWaiting()) await job.remove()`, returns: '处于 waiting 返回 true。', interview: '布尔助手提升可读性，但不是锁；状态可能在下一毫秒变为 active。', pitfall: '不要用先检查再修改实现强一致业务，捕获实际操作的状态错误。', officialUrl: `${JOB}#isWaiting` }),
  bullMqApi({ name: 'Job.isActive', group: 'Job 状态与控制', kind: 'function', signature: 'job.isActive(): Promise<boolean>', beginner: '判断任务是否已被 Worker 领取并正在持锁处理。', whenToUse: '展示运行状态或取消诊断时。', example: `const running = await job.isActive()`, returns: '处于 active 返回 true。', interview: 'active 不保证业务仍有进展；事件循环阻塞或下游卡死也可能保持/丢失 lock。', pitfall: '不要对 active Job 直接 remove；使用协作取消或业务取消标记。', officialUrl: `${JOB}#isActive` }),
  bullMqApi({ name: 'Job.isCompleted', group: 'Job 状态与控制', kind: 'function', signature: 'job.isCompleted(): Promise<boolean>', beginner: '查询 Redis，判断任务是否已经成功进入 completed 集合，并且对应 Job 记录目前仍被保留。', whenToUse: '短期查询是否可以读取 returnvalue 时。', example: `if (await job.isCompleted()) console.log(job.returnvalue)`, returns: '处于 completed 返回 true。', interview: '自动删除后无法再从 Queue 证明 completed，长期业务完成状态必须另存。', pitfall: '不要只用旧 job.returnvalue 判断状态，先刷新/查询并处理记录已删除。', officialUrl: `${JOB}#isCompleted` }),
  bullMqApi({ name: 'Job.isFailed', group: 'Job 状态与控制', kind: 'function', signature: 'job.isFailed(): Promise<boolean>', beginner: '判断 Job 是否最终位于 failed 集合。重试等待中的任务可能不是 failed。', whenToUse: '失败详情、人工重试按钮和告警确认时。', example: `if (await job.isFailed()) console.error(job.failedReason)`, returns: '处于 failed 返回 true。', interview: 'attempt 失败与 Job 最终失败不同；attempts/backoff 可让任务回到 delayed/waiting。', pitfall: '不要在每次 processor 抛错都立即人工重试，先让内建 attempts 策略完成。', officialUrl: `${JOB}#isFailed` }),
  bullMqApi({ name: 'Job.isDelayed', group: 'Job 状态与控制', kind: 'function', signature: 'job.isDelayed(): Promise<boolean>', beginner: '判断任务是否正在等待未来执行时间或 backoff 到期。', whenToUse: '延迟任务详情和重试退避诊断时。', example: `const delayed = await job.isDelayed()`, returns: '处于 delayed 返回 true。', interview: 'delayed 的目标时间是最早执行点，不是 SLA；到期后仍受并发和限流。', pitfall: '不要因 isDelayed 为 true 就重复 add；可能造成重复任务。', officialUrl: `${JOB}#isDelayed` }),
  bullMqApi({ name: 'Job.isWaitingChildren', group: 'Job 状态与控制', kind: 'function', signature: 'job.isWaitingChildren(): Promise<boolean>', beginner: '判断 Flow 中的父任务是否正停在 waiting-children 状态，等待一个或多个子任务满足依赖条件。', whenToUse: '排查父任务为什么没有被 Worker 领取时。', example: `if (await parent.isWaitingChildren()) inspectDependencies()`, returns: '处于 waiting-children 返回 true。', interview: '父任务状态由依赖结果驱动，不是 Worker 故障；子失败策略决定父是否继续。', pitfall: '不要手动 promote waiting-children；先处理真实依赖。', officialUrl: `${JOB}#isWaitingChildren` }),
  bullMqApi({ name: 'Job.changeDelay', group: 'Job 状态与控制', kind: 'function', signature: 'job.changeDelay(delay: number): Promise<void>', beginner: '修改 delayed Job 从现在起还要等待的毫秒数。只有任务当前处于 delayed 才能更改。', whenToUse: '用户改预约时间、动态推迟尚未执行任务时。', example: `await job.changeDelay(30 * 60_000)`, returns: '延迟更新时间完成的 Promise。', interview: 'changeDelay 修改调度分数，不是重新创建任务，可保留相同 jobId 和业务关联。', pitfall: '处理状态不符异常；delay 是相对时间，预约绝对时间要重新计算并考虑时区。', officialUrl: `${JOB}#changeDelay` }),
  bullMqApi({ name: 'Job.changePriority', group: 'Job 状态与控制', kind: 'function', signature: 'job.changePriority(opts: { priority?: number; lifo?: boolean }): Promise<void>', beginner: '调整等待任务的优先级或 LIFO 行为，让它在待处理集合中的顺序改变。', whenToUse: '业务紧急度变化，需要提升或降低尚未执行 Job 时。', example: `await job.changePriority({ priority: 1 })`, returns: '优先级修改完成的 Promise。', interview: 'priority 数字越小越优先，使用优先队列有性能成本；公平性常比绝对插队更重要。', pitfall: '不要频繁动态抖动优先级；active/completed 等状态不能按等待队列语义调整。', officialUrl: `${JOB}#changePriority` }),
  bullMqApi({ name: 'Job.promote', group: 'Job 状态与控制', kind: 'function', signature: 'job.promote(): Promise<void>', beginner: '把单个 delayed Job 提前移动到 waiting/prioritized，使其尽快执行。', whenToUse: '取消单条任务的等待时间或人工立即执行时。', example: `await job.promote()`, returns: '提升完成的 Promise。', interview: 'promote 只消除 delay，不绕过 pause、concurrency、priority 或 rate limit。', pitfall: '仅对 delayed 使用；重复/错误状态会失败，调度器任务提前执行需谨慎。', officialUrl: `${JOB}#promote` }),
  bullMqApi({ name: 'Job.retry', group: 'Job 状态与控制', kind: 'function', signature: 'job.retry(state?: "failed" | "completed", opts?: RetryOptions): Promise<void>', beginner: '把一个已 failed（也可指定 completed）的 Job 移回等待队列重新处理。', whenToUse: '人工确认问题已修复，需要重跑单条任务时。', example: `await job.retry('failed')`, returns: '成功移回队列的 Promise。', interview: '人工 retry 与自动 attempts 分开；重跑必须依赖幂等 processor 和清晰的审计原因。', pitfall: 'locked、不存在或状态不匹配会抛错；不要重复产生付款、通知等副作用。', officialUrl: `${JOB}#retry` }),
  bullMqApi({ name: 'Job.remove', group: 'Job 状态与控制', kind: 'function', signature: 'job.remove(opts?: { removeChildren?: boolean }): Promise<void>', beginner: '从 Redis 完全删除这条 Job，可选择同时处理子任务；active 持锁时会抛错。', whenToUse: '取消尚未执行任务或清除单条历史记录时。', example: `await job.remove({ removeChildren: true })`, returns: '删除完成的 Promise。', interview: '删除任务记录与取消外部业务是两个层次；Flow 还需要考虑父子依赖完整性。', pitfall: '先做权限和状态检查；删除不可恢复，也不会回滚已执行副作用。', officialUrl: `${JOB}#remove` }),
  bullMqApi({ name: 'Job.discard', group: 'Job 状态与控制', kind: 'function', signature: 'job.discard(): void', beginner: '告诉 BullMQ：如果当前处理失败，不要再按 attempts 重试这条 Job。通常在 processor 判断为永久错误时调用后再抛错。', whenToUse: '输入无效、资源永久不存在等重试没有意义的错误时。', example: `if (!isValid(job.data)) {\n  job.discard()\n  throw new Error('invalid payload')\n}`, returns: '无返回值，修改当前 Job 的重试行为。', interview: '错误分类决定重试策略：瞬时错误退避重试，永久错误 discard，限流使用 RateLimitError。', pitfall: '不要对所有异常 discard；调用后仍需抛出/失败，且应记录不可重试原因。', officialUrl: `${JOB}#discard` }),
  bullMqApi({ name: 'Job.waitUntilFinished', group: 'Job 状态与控制', kind: 'function', signature: 'job.waitUntilFinished(queueEvents: QueueEvents, ttl?: number): Promise<Result>', beginner: '等待这条 Job 完成时返回 result，失败时 reject；依赖 QueueEvents 接收全局 completed/failed 事件。', whenToUse: '短任务的请求—后台任务桥接、测试或必须同步拿到结果时。', example: `const result = await job.waitUntilFinished(queueEvents, 30_000)`, returns: '成功时为 processor 返回值，失败或 ttl 超时时 reject。', interview: '这是基于事件的等待，不代表应把所有后台任务变同步 HTTP；长任务更适合返回 jobId 后轮询/推送。', pitfall: '必须复用并正确 close QueueEvents，设置 ttl；网络超时不等于任务被取消。', officialUrl: `${JOB}#waitUntilFinished` }),
  bullMqApi({ name: 'Job.getChildrenValues', group: 'Job 状态与控制', kind: 'function', signature: 'job.getChildrenValues<Values>(): Promise<Values>', beginner: '读取 Flow 中已成功完成子任务的 returnvalue，键通常是子 Job 的 qualified key。', whenToUse: '父 processor 需要汇总子任务结果时。', example: `const values = await parentJob.getChildrenValues<Record<string, ChildResult>>()`, returns: '子任务 key 到完成结果的对象。', interview: 'Flow 父任务等子完成后再运行，结果通过 Redis 依赖结构聚合；大结果不宜长期塞 Redis。', pitfall: '不要假设键就是简单 jobId；处理失败/忽略子项，并限制 returnvalue 大小。', officialUrl: `${JOB}#getChildrenValues` }),
  bullMqApi({ name: 'Job.getFailedChildrenValues', group: 'Job 状态与控制', kind: 'function', signature: 'job.getFailedChildrenValues(): Promise<Record<string, string>>', beginner: '读取 Flow 中失败子任务的 key 与失败原因，帮助父任务按策略降级或报告。', whenToUse: '使用 continueParentOnFailure、ignoreDependency 等 Flow 策略后，父任务仍需了解失败项时。', example: `const failures = await parentJob.getFailedChildrenValues()`, returns: '子任务 key 到 failedReason 的对象。', interview: 'Flow 的部分失败需要显式建模，不能只靠父任务异常；返回原因可用于补偿和聚合报告。', pitfall: 'failedReason 不是稳定结构化错误，生产建议另存 error code；避免把内部堆栈直接展示给用户。', officialUrl: `${JOB}#getFailedChildrenValues` }),
  bullMqApi({ name: 'Job.getDependencies', group: 'Job 状态与控制', kind: 'function', signature: 'job.getDependencies(opts?): Promise<JobDependencies>', beginner: '分页查询父 Job 的 processed、unprocessed、failed 或 ignored 子依赖，适合诊断大型 Flow。', whenToUse: '查看哪些子任务尚未完成、失败或已处理时。', example: `const deps = await parentJob.getDependencies({ unprocessed: { count: 50 } })`, returns: '按类别组织的依赖 key/值和游标信息。', interview: '依赖查询需要分页，因为 Flow 可能很大；父状态由这些依赖集合的迁移决定。', pitfall: '不要一次拉全量；Redis 版本和数据结构可能影响分页行为，按官方游标继续。', officialUrl: `${JOB}#getDependencies` }),
  bullMqApi({ name: 'Job.getDependenciesCount', group: 'Job 状态与控制', kind: 'function', signature: 'job.getDependenciesCount(opts?): Promise<Record<DependencyType, number>>', beginner: '只统计父 Job 各类子依赖数量，不加载每个子任务详情。', whenToUse: 'Flow 进度条、积压告警和轻量诊断时。', example: `const counts = await parentJob.getDependenciesCount({ processed: true, unprocessed: true })`, returns: '依赖类别到数量的对象。', interview: 'Flow 进度可由 processed/(processed+unprocessed+failed) 估算，但不同失败策略会改变业务完成定义。', pitfall: '计数是瞬时值；不要把 ignored/failed 简单算作成功。', officialUrl: `${JOB}#getDependenciesCount` }),
  bullMqApi({ name: 'Job.removeChildDependency', group: 'Job 状态与控制', kind: 'function', signature: 'job.removeChildDependency(): Promise<boolean>', beginner: '从父任务中移除当前子 Job 的依赖关系；若这是最后一个未处理依赖，父任务可能变为可运行。', whenToUse: '业务明确取消某个尚未完成的子分支，并希望父流程继续时。', example: `const removed = await childJob.removeChildDependency()`, returns: '关系存在并成功移除时为 true。', interview: '改变依赖边会改变 Flow 状态机，应视为业务决策并审计，而不是普通清理。', pitfall: '只对确知父子关系的 Job 使用；移除后父任务可能立即执行，确保其能处理缺失结果。', officialUrl: `${JOB}#removeChildDependency` }),
  bullMqApi({ name: 'Job.removeUnprocessedChildren', group: 'Job 状态与控制', kind: 'function', signature: 'job.removeUnprocessedChildren(): Promise<void>', beginner: '删除父 Job 下尚未处理的所有子任务；completed、failed、active/locked 等按官方规则保留或跳过。', whenToUse: '父流程已提前得出结果，需要取消剩余未开始分支时。', example: `await parentJob.removeUnprocessedChildren()`, returns: '清理完成的 Promise。', interview: '这是 Flow 的短路/取消工具，大量子项时可能较慢；正在 active 的子任务无法靠删除安全停止。', pitfall: '超过上千子项要评估成本；配合 processor 取消标记，避免遗漏已经领取的子任务。', officialUrl: `${JOB}#removeUnprocessedChildren` }),
  bullMqApi({ name: 'Job.removeDeduplicationKey', group: 'Job 状态与控制', kind: 'function', signature: 'job.removeDeduplicationKey(): Promise<boolean>', beginner: '如果当前 Job 仍是某个 deduplication key 的拥有者，就提前移除该键，让后续相同去重 id 的任务可以再次入队。', whenToUse: '去重窗口需要由业务提前结束，而不是等待 ttl 或任务生命周期自动清理时。', example: `const released = await job.removeDeduplicationKey()`, returns: '确实移除当前 Job 对应键时为 true。', interview: 'deduplication 控制“是否创建新 Job”，不等同业务幂等；键所有权检查可避免旧任务误删新任务的去重锁。', pitfall: '过早删除会允许重复入队；不要用 removeDebounceKey 旧名称混淆新 deduplication 语义。', officialUrl: `${JOB}#removeDeduplicationKey` }),
]

const eventApis = [
  bullMqApi({ name: 'QueueEvents', group: 'QueueEvents 全局事件', kind: 'class', signature: 'new QueueEvents(name: string, opts?: QueueEventsOptions)', beginner: 'QueueEvents 通过 Redis Streams 集中监听整条队列所有 Worker 产生的 completed、failed、progress、stalled 等事件。它需要专用阻塞 Redis 连接。', whenToUse: 'WebSocket 推送、集中指标、Job.waitUntilFinished 和跨 Worker 的统一事件处理时。', example: `const queueEvents = new QueueEvents('emails', { connection })\nawait queueEvents.waitUntilReady()`, returns: '一个持续消费队列事件流的 QueueEvents 实例。', interview: '与 Worker.on 的本地 EventEmitter 不同，QueueEvents 从 Redis Stream 消费全局事件，短暂断线更不易丢，但流会自动裁剪且不是永久日志。', pitfall: '不要与 Queue/Worker 复用需要阻塞读取的同一 Redis connection 实例；进程退出时 close，并将事件处理设计成幂等。', officialUrl: EVENTS }),
  bullMqApi({ name: 'QueueEvents.on', group: 'QueueEvents 全局事件', kind: 'function', signature: 'queueEvents.on(event: QueueEvent, listener): this', beginner: '持续监听某类全局队列事件。回调通常收到 jobId 和事件数据，而不是完整 Job，需要时再用 Queue.getJob 查询。', whenToUse: '持续推送任务进度、完成/失败监控和审计流水时。', example: `queueEvents.on('completed', ({ jobId, returnvalue }) => notify(jobId, returnvalue))\nqueueEvents.on('progress', ({ jobId, data }) => publishProgress(jobId, data))`, returns: 'QueueEvents 自身，支持链式注册。', interview: '事件是状态变化通知，不是状态本身；消费者重启、重复事件或 Job 已被删除时，都应能从业务状态恢复。', pitfall: '监听器不要执行长耗时同步逻辑；对外推送前验证订阅者与 jobId 的归属，并监听 error。', officialUrl: `${EVENTS}#on` }),
  bullMqApi({ name: 'QueueEvents.once', group: 'QueueEvents 全局事件', kind: 'function', signature: 'queueEvents.once(event: QueueEvent, listener): this', beginner: '只监听某类事件的下一次发生，触发后自动移除监听器。注意它是“队列下一次该事件”，不自动限定某个 jobId。', whenToUse: '测试、一次性启动信号或明确会在回调中筛选 jobId 的短期等待时。', example: `queueEvents.once('drained', () => console.log('队列暂时已清空'))`, returns: 'QueueEvents 自身。', interview: '等待具体 Job 更适合 job.waitUntilFinished，它会关联 jobId；裸 once(completed) 在并发队列中可能捕获别的任务。', pitfall: '不要用 once("completed") 等待指定任务；还要设置超时，避免监听器永久挂起。', officialUrl: `${EVENTS}#once` }),
  bullMqApi({ name: 'QueueEvents.off', group: 'QueueEvents 全局事件', kind: 'function', signature: 'queueEvents.off(event: QueueEvent, listener): this', beginner: '移除之前注册的同一个监听函数，避免组件卸载或请求结束后继续收到事件。', whenToUse: '取消订阅、测试清理和临时监听器生命周期结束时。', example: `const listener = payload => publish(payload)\nqueueEvents.on('progress', listener)\nqueueEvents.off('progress', listener)`, returns: 'QueueEvents 自身。', interview: 'EventEmitter 取消订阅依赖同一函数引用；匿名函数无法用另一个匿名函数正确移除。', pitfall: '长生命周期服务要清理临时监听器，否则出现内存泄漏和重复通知。', officialUrl: `${EVENTS}#off` }),
  bullMqApi({ name: 'QueueEvents.run', group: 'QueueEvents 全局事件', kind: 'function', signature: 'queueEvents.run(): Promise<void>', beginner: '手动启动 QueueEvents 的事件消费循环。构造时设置 autorun:false 才需要显式调用，默认会自动运行。', whenToUse: '希望先注册监听器、初始化推送依赖，再开始消费事件时。', example: `const events = new QueueEvents('emails', { connection, autorun: false })\nevents.on('failed', handleFailure)\nvoid events.run()`, returns: '消费循环停止时完成的 Promise。', interview: '与 Worker.run 类似，它是长生命周期循环；启动顺序可避免初始事件在监听器注册前被应用忽略。', pitfall: '不要重复 run；捕获 Promise 错误，并保证 close 能结束阻塞读取。', officialUrl: `${EVENTS}#run` }),
  bullMqApi({ name: 'QueueEvents.close', group: 'QueueEvents 全局事件', kind: 'function', signature: 'queueEvents.close(): Promise<void>', beginner: '停止 QueueEvents 的 Redis Stream 消费循环，并优雅关闭它占用的专用阻塞 Redis 连接。', whenToUse: '进程退出、测试结束或不再需要全局监听时。', example: `await queueEvents.close()`, returns: '关闭完成的 Promise。', interview: '专用阻塞连接是 QueueEvents 的资源成本；graceful shutdown 应先停止接收新请求，再关闭事件消费。', pitfall: '关闭后等待中的 waitUntilFinished 可能无法收到结果；按正确顺序关停并设置超时。', officialUrl: `${EVENTS}#close` }),
  bullMqApi({ name: 'QueueEvents.waitUntilReady', group: 'QueueEvents 全局事件', kind: 'function', signature: 'queueEvents.waitUntilReady(): Promise<RedisClient>', beginner: '等待事件消费者的 Redis 连接就绪，确保监听基础设施可用。', whenToUse: '启动探针、集成测试和在调用 Job.waitUntilFinished 前确认连接时。', example: `await queueEvents.waitUntilReady()`, returns: '已连接的 Redis client。', interview: '事件通道 readiness 与 Queue 生产、Worker 消费是不同依赖，应分别监控。', pitfall: '连接 ready 不代表事件处理器没有异常；同时监控 error 和消费延迟。', officialUrl: `${EVENTS}#waitUntilReady` }),
]

const flowApis = [
  bullMqApi({ name: 'FlowProducer', group: 'Flow 父子任务', kind: 'class', signature: 'new FlowProducer(opts?: QueueBaseOptions)', beginner: 'FlowProducer 原子创建一棵父子 Job 树。子任务先执行，全部满足依赖后父任务才进入 waiting；不同节点可以属于不同队列。', whenToUse: '任务有明确 DAG/树依赖，例如“并行转码多个片段，最后合并视频”时。', example: `const flow = new FlowProducer({ connection })`, returns: '可添加、查询 Flow 的生产者实例。', interview: 'Flow 是 Redis 中的依赖编排，适合树状 fan-out/fan-in；它不是任意循环工作流引擎，节点 processor 仍需幂等。', pitfall: '不同队列必须使用兼容 prefix/连接；避免超大树一次创建，并设计子失败时父任务的策略。', officialUrl: FLOW }),
  bullMqApi({ name: 'FlowProducer.add', group: 'Flow 父子任务', kind: 'function', signature: 'flowProducer.add(flow: FlowJob, opts?: FlowOpts): Promise<JobNode>', beginner: '原子写入一棵 Flow：要么整棵树全部添加成功，要么不添加。children 先运行，父 processor 可读取子结果。', whenToUse: '一次创建单个多步骤父子任务图时。', example: `const tree = await flow.add({\n  name: 'merge', queueName: 'video', data: {},\n  children: files.map(file => ({ name: 'transcode', queueName: 'video', data: { file } })),\n})`, returns: '包含父 Job 与 children JobNode 的树。', interview: '原子创建避免只写入半棵依赖树；执行过程仍跨多个 Worker，属于最终完成而非单事务。', pitfall: 'Flow job opts 不支持所有普通 repeat/dedup 组合；跨队列权限与失败传播策略要逐节点配置。', officialUrl: `${FLOW}#add` }),
  bullMqApi({ name: 'FlowProducer.addBulk', group: 'Flow 父子任务', kind: 'function', signature: 'flowProducer.addBulk(flows: FlowJob[]): Promise<JobNode[]>', beginner: '一次原子添加多棵 Flow 树，减少 Redis 往返。', whenToUse: '批量创建多个彼此独立的父子任务图时。', example: `const trees = await flow.addBulk(requests.map(buildFlow))`, returns: '按输入顺序返回 JobNode[]。', interview: '批量 Flow 提高写入效率，但单次 Lua/事务负载也更大，应按树大小分批。', pitfall: '不要提交无限大的 flows；为每棵树设计业务幂等标识，整体失败后安全重试。', officialUrl: `${FLOW}#addBulk` }),
  bullMqApi({ name: 'FlowProducer.getFlow', group: 'Flow 父子任务', kind: 'function', signature: 'flowProducer.getFlow(opts: NodeOpts): Promise<JobNode>', beginner: '从指定 queueName/jobId 读取 Flow 节点，并可按 depth、maxChildren 等选项展开子树。', whenToUse: 'Flow 详情页、依赖诊断和查看父子执行状态时。', example: `const tree = await flow.getFlow({ id: parentId, queueName: 'video', depth: 3, maxChildren: 100 })`, returns: 'JobNode 树。', interview: 'Flow 查询必须限制深度和每层子数，否则大图会产生大量 Redis 读取和内存对象。', pitfall: '不要默认递归拉完整生产 Flow；结果是变化中的视图，并需校验 job 业务归属。', officialUrl: `${FLOW}#getFlow` }),
  bullMqApi({ name: 'FlowProducer.close', group: 'Flow 父子任务', kind: 'function', signature: 'flowProducer.close(): Promise<void>', beginner: '优雅关闭 FlowProducer 的 Redis 连接。', whenToUse: '进程退出、测试结束和生产者生命周期结束时。', example: `await flow.close()`, returns: '连接关闭完成的 Promise。', interview: 'FlowProducer 也应作为长生命周期资源复用，避免每次建树都重新连接。', pitfall: '不要在 add/addBulk 仍在途时关闭；统一管理关停顺序。', officialUrl: `${FLOW}#close` }),
  bullMqApi({ name: 'FlowProducer.waitUntilReady', group: 'Flow 父子任务', kind: 'function', signature: 'flowProducer.waitUntilReady(): Promise<RedisClient>', beginner: '等待 FlowProducer Redis 连接可用。', whenToUse: '启动初始化或 readiness 必须确认 Flow 可创建时。', example: `await flow.waitUntilReady()`, returns: '已连接的 Redis client。', interview: '依赖图创建是关键写路径，连接失败应让生产入口 fail fast，而不是声称任务已受理。', pitfall: '设置启动和请求超时，不要用返回 client 修改 BullMQ 内部依赖 key。', officialUrl: `${FLOW}#waitUntilReady` }),
]

const schedulerAndRateApis = [
  bullMqApi({ name: 'JobScheduler', group: '调度、重复与限流', kind: 'class', signature: 'Queue.upsertJobScheduler(id, repeatOpts, template?)', beginner: 'BullMQ v5.16+ 的 Job Scheduler 是重复任务“工厂”。学习者通过 Queue 的 upsert/get/list/remove 方法使用，不应直接 new 内部 JobScheduler 类。', whenToUse: '按 every 间隔、cron pattern 或自定义 repeat strategy 持续产生任务时。', example: `await queue.upsertJobScheduler('daily-report',\n  { pattern: '0 15 3 * * *' },\n  { name: 'report', data: { scope: 'daily' } },\n)`, returns: 'upsert 会返回调度器产生的第一条 delayed Job；后续按调度规则继续产生。', interview: 'Scheduler 只在上一条任务开始处理后安排下一条，因此繁忙队列下频率可能低于名义间隔；它不是固定并发的无限 cron 生产器。', pitfall: '使用稳定 scheduler id 做 upsert，部署重复执行不会创建多份；调度 Job 不能自定义 jobId，生产频率也不保证硬实时。', officialUrl: 'https://docs.bullmq.io/guide/job-schedulers' }),
  bullMqApi({ name: 'QueueScheduler (deprecated)', group: '调度、重复与限流', kind: 'class', signature: 'new QueueScheduler(name, opts?) // v5 不再需要', beginner: 'QueueScheduler 是 BullMQ 旧版用于 delayed、stalled、retry 的独立组件；官方说明从 BullMQ 2.0 起已弃用，v5 不应再部署它。当前 stalled 由 Worker 处理，重复调度使用 Job Scheduler。', whenToUse: '只在维护 BullMQ 1.x 旧系统、阅读历史代码或迁移方案时认识它；新 v5 项目不要使用。', example: `// BullMQ 5.x：不创建 QueueScheduler\nconst worker = new Worker('emails', processor, { connection })\nawait queue.upsertJobScheduler('digest', { every: 60_000 })`, returns: 'v5 新代码无返回值，因为不应实例化；历史 close() 用于关闭旧 scheduler。', interview: '常见面试陷阱：旧教程说 delayed/retry 必须 QueueScheduler，但官方 v2+ 已取消该要求；v5 的 Job Scheduler 是“产生重复 Job”，不是旧 QueueScheduler 的同名替代实现。', pitfall: '不要照搬 BullMQ 1.x 教程增加多余进程；迁移前核对实际 major version，避免把 JobScheduler 与 QueueScheduler 混为一谈。', officialUrl: 'https://docs.bullmq.io/guide/queuescheduler' }),
  bullMqApi({ name: 'Queue.upsertJobScheduler', group: '调度、重复与限流', kind: 'function', signature: 'queue.upsertJobScheduler(id, repeatOpts, jobTemplate?): Promise<Job>', beginner: '按稳定 id 创建或更新 Job Scheduler；重复部署同一配置不会叠加多个调度器，因此比旧 repeatable add 更适合生产配置。', whenToUse: '创建/更新 every 或 cron 重复任务，并希望部署幂等时。', example: `const first = await queue.upsertJobScheduler('cleanup', { every: 3600_000 }, {\n  name: 'cleanup', data: {}, opts: { attempts: 3 },\n})`, returns: '当前调度器产生的第一条/下一条 Job。', interview: 'upsert 把“定义重复规则”与“产生的每次 Job”分开；scheduler id 是配置身份，单次 Job id 由系统生成。', pitfall: '更新 id 会改现有调度规则，换 id 会新增一份；cron 包含秒字段并注意时区。', officialUrl: `${QUEUE}#upsertJobScheduler` }),
  bullMqApi({ name: 'Queue.getJobScheduler', group: '调度、重复与限流', kind: 'function', signature: 'queue.getJobScheduler(id: string): Promise<JobSchedulerJson | undefined>', beginner: '按 scheduler id 读取它的 repeat 规则、模板和下一次执行信息。', whenToUse: '调度器详情页、配置漂移检查和修改前确认时。', example: `const scheduler = await queue.getJobScheduler('cleanup')`, returns: 'JobSchedulerJson，找不到时为空。', interview: '查询的是调度定义，不是某次产生的 Job；调度状态与单次任务状态属于两个层次。', pitfall: '不要用下一次时间承诺准点完成，实际执行还受队列负载和 Worker 能力影响。', officialUrl: `${QUEUE}#getJobScheduler` }),
  bullMqApi({ name: 'Queue.getJobSchedulers', group: '调度、重复与限流', kind: 'function', signature: 'queue.getJobSchedulers(start?, end?, asc?): Promise<JobSchedulerJson[]>', beginner: '分页列出队列中的 Job Scheduler 配置。', whenToUse: '调度管理页、审计和启动时检查重复定义时。', example: `const schedulers = await queue.getJobSchedulers(0, 49, true)`, returns: '调度器 JSON 数组。', interview: '调度器目录应作为基础设施配置治理，理想状态由代码 upsert，列表用于发现漂移而非人工随意修改。', pitfall: '始终分页；不要把 legacy repeatable 与新 scheduler 数据结构混用。', officialUrl: `${QUEUE}#getJobSchedulers` }),
  bullMqApi({ name: 'Queue.getJobSchedulersCount', group: '调度、重复与限流', kind: 'function', signature: 'queue.getJobSchedulersCount(): Promise<number>', beginner: '统计当前队列的新式 Job Scheduler 数量。', whenToUse: '配置完整性检查和管理面板概览时。', example: `const count = await queue.getJobSchedulersCount()`, returns: '调度器数量。', interview: '数量异常可提示重复部署 id 或配置缺失，但还需比较具体 id/规则。', pitfall: 'count 正确不代表规则正确；做声明式配置 diff。', officialUrl: `${QUEUE}#getJobSchedulersCount` }),
  bullMqApi({ name: 'Queue.removeJobScheduler', group: '调度、重复与限流', kind: 'function', signature: 'queue.removeJobScheduler(id: string): Promise<boolean>', beginner: '删除 Job Scheduler，阻止它继续产生新 Job；已经产生并进入队列的 Job 不一定一起删除。', whenToUse: '下线定时任务或替换 scheduler id 时。', example: `const removed = await queue.removeJobScheduler('cleanup')`, returns: '找到并删除时为 true。', interview: '删除“生产规则”与清理“已生产实例”是两件事；运维下线应分别决定历史/等待 Job 怎么处理。', pitfall: '删除前确认环境和 id；如果需要取消已产生 Job，再按业务标识安全查找和处理。', officialUrl: `${QUEUE}#removeJobScheduler` }),
  bullMqApi({ name: 'Queue.getRepeatableJobs', group: '调度、重复与限流', kind: 'function', signature: 'queue.getRepeatableJobs(start?, end?, asc?): Promise<RepeatableJob[]>', beginner: '读取旧版 repeatable jobs 配置。BullMQ v5.16+ 新功能应优先 Job Scheduler，但迁移和兼容旧数据仍会用到它。', whenToUse: '维护旧 repeat 任务、迁移到 Job Scheduler 或排查历史配置时。', example: `const legacy = await queue.getRepeatableJobs(0, 49, true)`, returns: '旧重复任务描述数组，包括 key、name、next 等。', interview: '新旧重复机制可能共享部分 Redis 结构但身份规则不同，迁移需按官方 API 区分，不能只按 key 字符串猜测。', pitfall: '新代码不要继续扩大 legacy repeat 使用；列表分页，并保留 key 供精确删除。', officialUrl: `${QUEUE}#getRepeatableJobs` }),
  bullMqApi({ name: 'Queue.removeRepeatable', group: '调度、重复与限流', kind: 'function', signature: 'queue.removeRepeatable(name, repeatOpts, jobId?): Promise<boolean>', beginner: '用与创建时一致的 name 和 repeat options 删除旧版重复任务配置。参数必须精确匹配。', whenToUse: '旧系统仍知道原始 repeat 配置，需要停止该重复任务时。', example: `await queue.removeRepeatable('digest', { pattern: '0 0 * * * *' })`, returns: '成功删除匹配配置时为 true。', interview: 'repeat identity 由名称与 repeat options 共同计算，配置不一致就找不到；新 Scheduler 用显式 id 简化了管理。', pitfall: 'cron/every/tz 等必须与添加时相同；优先迁移到 removeJobScheduler(id)。', officialUrl: `${QUEUE}#removeRepeatable` }),
  bullMqApi({ name: 'Queue.removeRepeatableByKey', group: '调度、重复与限流', kind: 'function', signature: 'queue.removeRepeatableByKey(key: string): Promise<boolean>', beginner: '直接用 getRepeatableJobs 返回的旧 repeat key 删除配置，避免重新拼完全相同的 repeat options。', whenToUse: '旧重复任务管理页或迁移脚本已经拿到精确 key 时。', example: `for (const repeat of legacy) await queue.removeRepeatableByKey(repeat.key)`, returns: '删除成功时为 true。', interview: '按 key 删除更精确但 key 是基础设施标识；新 Job Scheduler 采用业务可读 id。', pitfall: 'key 属于特定 queue/prefix；不要接受用户任意 key，也不要用它删除新式 scheduler。', officialUrl: `${QUEUE}#removeRepeatableByKey` }),
  bullMqApi({ name: 'Queue.setGlobalRateLimit', group: '调度、重复与限流', kind: 'function', signature: 'queue.setGlobalRateLimit(max: number, duration: number): Promise<number>', beginner: '设置整条队列跨所有 Worker 的固定速率上限，例如每 1000ms 最多处理 10 条。它控制开始处理的速率，不是单实例 concurrency。', whenToUse: '保护有 QPS 限制的共享第三方服务或控制全局吞吐时。', example: `await queue.setGlobalRateLimit(10, 1000)`, returns: 'Redis 设置结果。', interview: 'rate limit 限制时间窗口内启动次数，concurrency 限制同时 active 数；短任务常受 rate limit，长任务常受 concurrency。', pitfall: 'duration 单位是毫秒；Worker opts 的 limiter 不会覆盖更严格的全局限制，设置后观察积压。', officialUrl: `${QUEUE}#setGlobalRateLimit` }),
  bullMqApi({ name: 'Queue.getGlobalRateLimit', group: '调度、重复与限流', kind: 'function', signature: 'queue.getGlobalRateLimit(): Promise<{ max; duration } | null>', beginner: '读取队列当前跨所有 Worker 生效的固定限流配置，包括一个时间窗口允许的 max 数量和 duration 毫秒。', whenToUse: '运维展示、配置审计和动态调整前确认时。', example: `const limit = await queue.getGlobalRateLimit()`, returns: 'max/duration 配置或未设置时的空值。', interview: '配置值不等于当前剩余额度；当前还需等待多久用 getRateLimitTtl。', pitfall: '不要把 null 当 max=0；并注意多个部署同时修改配置的漂移。', officialUrl: `${QUEUE}#getGlobalRateLimit` }),
  bullMqApi({ name: 'Queue.getRateLimitTtl', group: '调度、重复与限流', kind: 'function', signature: 'queue.getRateLimitTtl(maxJobs?: number): Promise<number>', beginner: '查询当前限流还剩多少毫秒才释放；返回 0/非正值通常表示当前不受等待。可选 maxJobs 用于判断指定数量任务的窗口。', whenToUse: '运维解释“为什么有 Worker 但不取任务”、返回 Retry-After 或诊断手动限流时。', example: `const ttl = await queue.getRateLimitTtl()`, returns: '剩余限流 TTL 毫秒数。', interview: 'TTL 是瞬时调度状态，可帮助区分“没有 Worker”“全局并发已满”和“被速率限制”。', pitfall: '不要用高频轮询制造 Redis 压力；时间到也不保证立即执行，还受其他闸门影响。', officialUrl: `${QUEUE}#getRateLimitTtl` }),
  bullMqApi({ name: 'Queue.removeGlobalRateLimit', group: '调度、重复与限流', kind: 'function', signature: 'queue.removeGlobalRateLimit(): Promise<number>', beginner: '移除队列固定全局限流配置，让吞吐恢复由 Worker concurrency、全局并发和下游能力决定。', whenToUse: '第三方限制取消或迁移到新的限流策略时。', example: `await queue.removeGlobalRateLimit()`, returns: 'Redis 删除结果。', interview: '解除限流会释放积压，属于容量变更；应渐进执行并监控下游错误率。', pitfall: '高 backlog 时直接移除会产生流量洪峰；先评估总 Worker concurrency。', officialUrl: `${QUEUE}#removeGlobalRateLimit` }),
  bullMqApi({ name: 'WorkerOptions.limiter', group: '调度、重复与限流', kind: 'interface', maturity: 'type-only', signature: 'limiter: { max: number; duration: number }', beginner: '在 Worker 配置固定限流，例如 1 秒最多处理 100 条。多个 Worker 共享队列时限制由 Redis 协调，不是每个 Worker 各算一份。', whenToUse: '部署 Worker 时已知稳定 QPS 上限，并希望声明式配置处理速率。', example: `const worker = new Worker('emails', processor, {\n  connection,\n  limiter: { max: 100, duration: 1000 },\n})`, returns: '仅配置类型；运行后 Worker 按限制领取任务。', interview: '固定 limiter 与 worker.rateLimit 的区别：前者预设窗口，后者根据 429/Retry-After 动态暂停。', pitfall: '限流按队列全局协调，不支持旧版 groupKey 分组限流；多租户差异通常拆队列或在业务层治理。', officialUrl: 'https://docs.bullmq.io/guide/rate-limiting' }),
]

const metricsApis = [
  bullMqApi({ name: 'Queue.getMetrics', group: 'Metrics 指标', kind: 'function', signature: 'queue.getMetrics(type: "completed" | "failed", start?, end?): Promise<Metrics>', beginner: '读取 Worker 按分钟记录的 completed 或 failed 计数时间序列，以及从启用以来的累计 count。只有 Worker 配置 metrics 后才有数据。', whenToUse: '绘制最近吞吐/失败趋势、容量分析和简单队列监控时。', example: `const metrics = await queue.getMetrics('completed', 0, 60 * 24 - 1)\nconsole.log(metrics.count, metrics.data)`, returns: '包含 meta、data、count 的 Metrics；data 是每分钟计数。', interview: '内建 metrics 是一分钟粒度的轻量 Redis 序列，适合趋势但不是完整 APM；count 为累计计数，不是所选窗口之和。', pitfall: '先在 Worker 设置 maxDataPoints；不要使用文档标明内部的 prevTS/prevCount，也不要期待秒级延迟分位数。', officialUrl: `${QUEUE}#getMetrics` }),
  bullMqApi({ name: 'Queue.exportPrometheusMetrics', group: 'Metrics 指标', kind: 'function', signature: 'queue.exportPrometheusMetrics(globalVariables?): Promise<string>', beginner: '把当前队列的 Job 状态计数导出为 Prometheus 文本格式，可直接作为监控抓取端点响应。', whenToUse: '已有 Prometheus，需要暴露 waiting、active、completed、failed 等队列指标时。', example: `app.get('/metrics', async (_req, res) => {\n  res.type('text/plain').send(await queue.exportPrometheusMetrics({ service: 'mailer' }))\n})`, returns: 'Prometheus exposition format 字符串。', interview: 'Prometheus 拉取当前状态，BullMQ getMetrics 提供分钟历史；生产还应增加处理时长、重试和业务 SLO 指标。', pitfall: 'globalVariables 标签必须低基数；不要放 jobId/userId。保护 metrics 端点并避免每次创建 Queue。', officialUrl: `${QUEUE}#exportPrometheusMetrics` }),
  bullMqApi({ name: 'WorkerOptions.metrics', group: 'Metrics 指标', kind: 'interface', maturity: 'type-only', signature: 'metrics: { maxDataPoints?: MetricsTime | number }', beginner: '在 Worker 上开启 BullMQ 内建每分钟指标，并指定 Redis 最多保留多少个数据点。所有处理该队列的 Worker 应采用一致保留策略。', whenToUse: '需要 Queue.getMetrics 查询 completed/failed 历史趋势时。', example: `const worker = new Worker('emails', processor, {\n  connection,\n  metrics: { maxDataPoints: MetricsTime.ONE_WEEK * 2 },\n})`, returns: '仅配置；Worker 处理任务时会写入指标数据。', interview: '两个星期的分钟点数量有限、内存成本可控；这是计数指标，不包含每个 Job 的完整 trace。', pitfall: '未配置就不会自动出现历史 data；保留点过大仍占 Redis，跨 Worker 配置要一致。', officialUrl: 'https://docs.bullmq.io/guide/metrics' }),
]

export const BULLMQ_FRAMEWORK_API_EXPECTED_COUNT = 108

export const bullMqFrameworkApis: FrameworkApiReference[] = [
  ...queueApis,
  ...workerApis,
  ...jobApis,
  ...eventApis,
  ...flowApis,
  ...schedulerAndRateApis,
  ...metricsApis,
]

if (bullMqFrameworkApis.length !== BULLMQ_FRAMEWORK_API_EXPECTED_COUNT) {
  throw new Error(`BullMQ framework API catalog expected ${BULLMQ_FRAMEWORK_API_EXPECTED_COUNT} entries, received ${bullMqFrameworkApis.length}`)
}
